const createOrUpdateFileInputSchema = object({
	owner: schemas_string().describe("Repository owner"),
	repo: schemas_string().describe("Repository name"),
	path: schemas_string().describe("Path to the file in the repository"),
	message: schemas_string().describe("Commit message"),
	content: schemas_string().describe("File content (plain text, will be base64-encoded automatically)"),
	branch: schemas_string().optional().describe("Branch to commit to (defaults to the default branch)"),
	sha: schemas_string().optional().describe("SHA of the file being replaced (required when updating an existing file)")
});
const createOrUpdateFileDescription = "Create or update a file in a GitHub repository. Provide the SHA when updating an existing file.";
/** Idempotent when updating with sha and content is unchanged. Not idempotent for new commits. */
async function createOrUpdateFileCore({ token, owner, repo, path, message, content, branch, sha, author, committer, coAuthors }) {
	const octokit = createOctokit(token);
	if (sha) {
		const branchName = branch || (await octokit.rest.repos.get({
			owner,
			repo
		})).data.default_branch;
		try {
			const { data: fileData } = await octokit.rest.repos.getContent({
				owner,
				repo,
				path,
				ref: branchName
			});
			if (!Array.isArray(fileData) && fileData.type === "file") {
				if (Buffer.from(fileData.content, "base64").toString("utf-8") === content) return {
					path: fileData.path,
					sha: fileData.sha,
					skipped: true,
					message: "Content unchanged; no commit created"
				};
			}
		} catch {}
	}
	if (!author && !committer) try {
		const branchName = branch || (await octokit.rest.repos.get({
			owner,
			repo
		})).data.default_branch;
		const { data: ref } = await octokit.rest.git.getRef({
			owner,
			repo,
			ref: `heads/${branchName}`
		});
		const [headline, ...rest] = composeCommitMessage(message, coAuthors).split("\n");
		const body = rest.join("\n").replace(/^\n+/, "") || void 0;
		const result = await createCommitOnBranch(octokit, {
			owner,
			repo,
			branch: branchName,
			expectedHeadOid: ref.object.sha,
			headline,
			body,
			additions: [{
				path,
				contents: Buffer.from(content).toString("base64")
			}]
		});
		return {
			path,
			sha: gitBlobSha(content),
			commitSha: result.commitSha,
			commitUrl: result.commitUrl
		};
	} catch (error) {
		if (error instanceof CreateCommitOnBranchError && error.reason === "stale_data") throw error;
		const msg = error instanceof Error ? error.message : String(error);
		console.warn(`[github-tools] Signed commit failed, using REST API: ${msg}`);
	}
	const encoded = Buffer.from(content).toString("base64");
	const finalMessage = composeCommitMessage(message, coAuthors);
	const { data } = await octokit.rest.repos.createOrUpdateFileContents({
		owner,
		repo,
		path,
		message: finalMessage,
		content: encoded,
		branch,
		sha,
		author,
		committer
	});
	return {
		path: data.content?.path,
		sha: data.content?.sha,
		commitSha: data.commit.sha,
		commitUrl: data.commit.html_url
	};
}
