//#region src/core/model-output.ts
const MAX_PATCH_LENGTH = 4e3;
const MAX_CONTENT_LENGTH = 5e4;
function truncateText(text, maxLength) {
	if (text.length <= maxLength) return text;
	return `${text.slice(0, maxLength)}\n\n[truncated: ${text.length - maxLength} more characters]`;
}
function listPullRequestFilesToModelOutput({ output }) {
	return {
		type: "json",
		value: output.map((file) => ({
			...file,
			patch: file.patch ? truncateText(file.patch, MAX_PATCH_LENGTH) : file.patch
		}))
	};
}
function getCommitToModelOutput({ output }) {
	const commit = output;
	return {
		type: "json",
		value: {
			...commit,
			files: commit.files?.map((file) => ({
				...file,
				patch: file.patch ? truncateText(file.patch, MAX_PATCH_LENGTH) : file.patch
			}))
		}
	};
}
function getFileContentToModelOutput({ output }) {
	const result = output;
	if ("content" in result && result.content.length > MAX_CONTENT_LENGTH) return {
		type: "json",
		value: {
			...result,
			content: truncateText(result.content, MAX_CONTENT_LENGTH)
		}
	};
	return {
		type: "json",
		value: result
	};
}
