/** Idempotent when the issue is already closed. */
async function closeIssueCore({ token, owner, repo, issueNumber, stateReason }) {
	const octokit = createOctokit(token);
	const { data: existing } = await octokit.rest.issues.get({
		owner,
		repo,
		issue_number: issueNumber
	});
	if (existing.state === "closed") return {
		number: existing.number,
		title: existing.title,
		state: existing.state,
		url: existing.html_url,
		closedAt: existing.closed_at
	};
	const { data } = await octokit.rest.issues.update({
		owner,
		repo,
		issue_number: issueNumber,
		state: "closed",
		state_reason: stateReason
	});
	return {
		number: data.number,
		title: data.title,
		state: data.state,
		url: data.html_url,
		closedAt: data.closed_at
	};
}
