const BLAME_QUERY = `
  query ($owner: String!, $name: String!, $expression: String!, $path: String!) {
    repository(owner: $owner, name: $name) {
      object(expression: $expression) {
        ... on Commit {
          oid
          blame(path: $path) {
            ranges {
              startingLine
              endingLine
              age
              commit {
                oid
                abbreviatedOid
                messageHeadline
                authoredDate
                url
                author {
                  name
                  email
                  user {
                    login
                  }
                }
              }
            }
          }
        }
      }
    }
  }
`;
