const getBlameInputSchema = object({
	owner: schemas_string().describe("Repository owner"),
	repo: schemas_string().describe("Repository name"),
	path: schemas_string().describe("Path to the file in the repository"),
	ref: schemas_string().optional().describe("Branch name, tag, or commit SHA (defaults to the repository default branch)"),
	line: schemas_number().int().positive().optional().describe("If set, only return blame ranges that include this line number"),
	lineStart: schemas_number().int().positive().optional().describe("When used with lineEnd, only return ranges overlapping this window"),
	lineEnd: schemas_number().int().positive().optional().describe("When used with lineStart, only return ranges overlapping this window")
});
const getBlameDescription = "Line-level git blame for a file at a commit-like ref (branch, tag, or SHA). Returns contiguous ranges mapping lines to the commits that last modified them — use this to see who introduced a line and when (GitHub GraphQL API).";
async function getBlameCore({ token, owner, repo, path, ref, line, lineStart, lineEnd }) {
	const octokit = createOctokit(token);
	let expression = ref;
	if (!expression) {
		const { data } = await octokit.rest.repos.get({
			owner,
			repo
		});
		expression = data.default_branch;
	}
	const data = await octokit.graphql(BLAME_QUERY, {
		owner,
		name: repo,
		expression,
		path
	});
	if (!data.repository) return { error: `Repository not found: ${owner}/${repo}` };
	const obj = data.repository.object;
	if (!obj?.oid || !obj?.blame) return { error: `Ref "${expression}" did not resolve to a commit for this repository (or the path is invalid). Pass a branch name, tag, or full commit SHA.` };
	let ranges = obj.blame.ranges.map((r) => ({
		startingLine: r.startingLine,
		endingLine: r.endingLine,
		age: r.age,
		commit: {
			sha: r.commit.oid,
			abbreviatedSha: r.commit.abbreviatedOid,
			messageHeadline: r.commit.messageHeadline,
			authoredDate: r.commit.authoredDate,
			url: r.commit.url,
			authorName: r.commit.author?.name ?? null,
			authorEmail: r.commit.author?.email ?? null,
			authorLogin: r.commit.author?.user?.login ?? null
		}
	}));
	if (line != null) ranges = ranges.filter((r) => line >= r.startingLine && line <= r.endingLine);
	else if (lineStart != null || lineEnd != null) {
		const start = lineStart ?? 1;
		const end = lineEnd ?? Number.MAX_SAFE_INTEGER;
		ranges = ranges.filter((r) => r.endingLine >= start && r.startingLine <= end);
	}
	return {
		ref: expression,
		tipSha: obj.oid,
		path,
		rangeCount: ranges.length,
		ranges
	};
}
