const updateGistInputSchema = object({
	gistId: schemas_string().describe("Gist ID"),
	description: schemas_string().optional().describe("New gist description"),
	files: record(schemas_string(), object({ content: schemas_string().describe("New file content") })).optional().describe("Files to add or update, keyed by filename"),
	filesToDelete: array(schemas_string()).optional().describe("Filenames to remove from the gist")
});
const updateGistDescription = "Update an existing gist — edit description, update files, or remove files";
/** Not idempotent — each call applies a new revision. */
async function updateGistCore({ token, gistId, description, files, filesToDelete }) {
	const octokit = createOctokit(token);
	const fileUpdates = {};
	if (files) Object.assign(fileUpdates, files);
	if (filesToDelete) for (const name of filesToDelete) fileUpdates[name] = null;
	const { data } = await octokit.rest.gists.update({
		gist_id: gistId,
		description,
		files: fileUpdates
	});
	return {
		id: data.id,
		description: data.description,
		url: data.html_url,
		files: Object.keys(data.files ?? {})
	};
}
