/** Not idempotent — each call starts another run attempt. */
async function rerunWorkflowRunCore({ token, owner, repo, runId, onlyFailedJobs }) {
	const octokit = createOctokit(token);
	if (onlyFailedJobs) await octokit.rest.actions.reRunWorkflowFailedJobs({
		owner,
		repo,
		run_id: runId
	});
	else await octokit.rest.actions.reRunWorkflow({
		owner,
		repo,
		run_id: runId
	});
	return {
		rerun: true,
		runId,
		onlyFailedJobs
	};
}
